function refreshStudentSelect(){const sel=$('studentSelect');if(!sel)return;const old=sel.value;const eff=new Set(effectiveResults());const opts=RESULTS.map((r,i)=>({r,i})).filter(x=>eff.has(x.r)&&matchesQuery(x.r));sel.innerHTML=opts.length?opts.map(x=>'<option value="'+esc(resultKey(x.r,x.i))+'">'+esc(displayStudent(x.r))+' — '+esc(x.r.earned)+'/'+esc(x.r.total)+' b, známka '+esc(x.r.grade)+'</option>').join(''):'<option value="">Žádný student ve filtru</option>';if(old&&Array.from(sel.options).some(o=>o.value===old))sel.value=old;}
