function normStudentKey(s){return String(s||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');}
function rebuildDuplicateState(){const firstByDigest=new Map();RESULTS.forEach((r,i)=>{if(r.status!=='OK')return;r.exactDuplicate=false;r.exactDuplicateOf=-1;r.attemptConflict=false;const d=String(r.submissionDigest||'');if(d&&firstByDigest.has(d)){r.exactDuplicate=true;r.exactDuplicateOf=firstByDigest.get(d);}else if(d)firstByDigest.set(d,i);});const byStudent={};RESULTS.forEach((r,i)=>{if(r.status!=='OK'||r.exactDuplicate)return;const sk=normStudentKey(r.student);if(sk)(byStudent[sk]||(byStudent[sk]=[])).push(i);});Object.keys(byStudent).forEach(sk=>{if(byStudent[sk].length>1)byStudent[sk].forEach(i=>{RESULTS[i].attemptConflict=true;});});}
